public static boolean isSourceProperty(
        TaintedDataSymbolMap<SourceInfo> sourceSymbolMap,
        IPropertySymbol propertySymbol) {

    for (SourceInfo sourceInfo : sourceSymbolMap.getInfosForType(propertySymbol.getContainingType())) {
        if (sourceInfo.getTaintedProperties().contains(propertySymbol.getMetadataName())) {
            return true;
        }
    }

    return false;
}

public static boolean isSourceTransferProperty(
        TaintedDataSymbolMap<SourceInfo> sourceSymbolMap,
        IPropertyReferenceOperation propertyReferenceOperation) {


    if (propertyReferenceOperation.getInstance() == null ||
        !(propertyReferenceOperation.getInstance().getType() instanceof INamedTypeSymbol)) {
        return false;
    }

    INamedTypeSymbol namedType = (INamedTypeSymbol) propertyReferenceOperation.getInstance().getType();

    String name = propertyReferenceOperation.getMember().getName();

    if (!"CSharp".equals(propertyReferenceOperation.getMember().getLanguage()) &&
        propertyReferenceOperation.getMember().isIndexer()) {

        name = TaintedDataProperties.INDEXER_NAME;
    }

    return false;
}

public static boolean isSourceParameter(
        TaintedDataSymbolMap<SourceInfo> sourceSymbolMap,
        IParameterSymbol parameterSymbol,
        WellKnownTypeProvider wellKnownTypeProvider) {

    ISymbol containingSymbol = parameterSymbol.getContainingSymbol();

    for (SourceInfo sourceInfo : sourceSymbolMap.getInfosForType(containingSymbol.getContainingType())) {

        if (sourceInfo.getTaintedArguments().stream()
                .anyMatch(match -> match.test(parameterSymbol, wellKnownTypeProvider))) {
            return true;
        }
    }

    return false;
}

private static <TInfo> boolean tryResolveDependencies(TInfo info, WellKnownTypeProvider wellKnownTypeProvider) {

    for (String dependency : info.getDependencyFullTypeNames()) {
        INamedTypeSymbol typeSymbol = wellKnownTypeProvider.tryGetOrCreateTypeByMetadataName(dependency);

        if (typeSymbol == null) {
            return false;
        }
    }

    return true;
}

