private <T extends ITaintedDataInfo> TaintedDataSymbolMap<T> getFromMap(
        SinkKind sinkKind,
        Map<SinkKind, Supplier<TaintedDataSymbolMap<T>>> map) {

    Supplier<TaintedDataSymbolMap<T>> lazySourceSymbolMap = map.get(sinkKind);

    if (lazySourceSymbolMap != null) {
        return lazySourceSymbolMap.get();
    } else {
