static TaintedDataAbstractValue mergeTainted(
        TaintedDataAbstractValue value1,
        TaintedDataAbstractValue value2) {

    assert value1.getKind() == TaintedDataAbstractValueKind.TAINTED;
    assert value2.getKind() == TaintedDataAbstractValueKind.TAINTED;

    ImmutableSet<SymbolAccess> mergedSources = 
            ImmutableSet.<SymbolAccess>builder()
                        .addAll(value1.getSourceOrigins())
                        .addAll(value2.getSourceOrigins())
                        .build();

    return new TaintedDataAbstractValue(
            TaintedDataAbstractValueKind.TAINTED,
            mergedSources);
}

