@Override
public PropertySetAbstractValue merge(PropertySetAbstractValue value1, PropertySetAbstractValue value2) {
    int maxKnownCount = Math.max(value1.getKnownValuesCount(), value2.getKnownValuesCount());
    ArrayList<PropertySetAbstractValueKind> builder = new ArrayList<>(maxKnownCount);

    for (int i = 0; i < maxKnownCount; i++) {
        builder.add(mergeKind(value1.get(i), value2.get(i)));
    }

    return PropertySetAbstractValue.getInstance(builder);
}

