private void handlePossibleEscapingOperation(IOperation escapingOperation, Set<AbstractLocation> escapedLocations) {
    for (AbstractLocation escapedLocation : escapedLocations) {
        DisposeAbstractValue currentDisposeValue = CurrentAnalysisData.get(escapedLocation);
        if (currentDisposeValue != null && currentDisposeValue.getKind() != DisposeAbstractValueKind.UNKNOWN) {
            DisposeAbstractValue newDisposeValue = currentDisposeValue.withNewEscapingOperation(escapingOperation);
            setAbstractValue(escapedLocation, newDisposeValue);
        }
    }
}

