private boolean hasDisposableOwnershipTransferForConstructorParameter(IMethodSymbol containingMethod) {
    return containingMethod.getMethodKind() == MethodKind.CONSTRUCTOR &&
           containingMethod.getParameters().stream()
               .anyMatch(p -> disposeOwnershipTransferLikelyTypes.contains(p.getType()));
}

public boolean hasAnyDisposableCreationDescendant(ImmutableList<IOperation> operationBlocks, IMethodSymbol containingMethod) {
    return hasAnyOperationDescendant(operationBlocks, this::isDisposableCreation) ||
           hasDisposableOwnershipTransferForConstructorParameter(containingMethod);
}

public boolean isDisposableCreationOrDisposeOwnershipTransfer(AbstractLocation location, IMethodSymbol containingMethod) {
    if (location.getCreation() == null) {
        return location.getSymbol() != null &&
               location.getSymbol().getKind() == SymbolKind.PARAMETER &&
               hasDisposableOwnershipTransferForConstructorParameter(containingMethod);
    }

    return isDisposableCreation(location.getCreation());
}

