public static ControlFlowConditionKind negate(ControlFlowConditionKind controlFlowConditionKind) {
    switch (controlFlowConditionKind) {
        case WHEN_FALSE:
            return ControlFlowConditionKind.WHEN_TRUE;

        case WHEN_TRUE:
            return ControlFlowConditionKind.WHEN_FALSE;

        default:
            System.err.println("Unsupported conditional kind: " + controlFlowConditionKind);
            return controlFlowConditionKind;
    }
}

public static List<IOperation> descendantOperations(ControlFlowRegion controlFlowRegion, ControlFlowGraph cfg) {
    List<IOperation> result = new ArrayList<>();
    for (int i = controlFlowRegion.getFirstBlockOrdinal(); i <= controlFlowRegion.getLastBlockOrdinal(); i++) {
        BasicBlock block = cfg.getBlocks().get(i);
        result.addAll(block.descendantOperations());
    }
    return result;
}

public static boolean isLValueFlowCaptureReference(IFlowCaptureReferenceOperation flowCaptureReference) {
