void processNamespace(INamespaceSymbol namespaceSymbol) {
    for (INamespaceOrTypeSymbol child : namespaceSymbol.getMembers()) {
        if (child.getKind() == SymbolKind.NAMESPACE) {
            processNamespace((INamespaceSymbol) child);
        } else if (namespaceSymbol.isGlobalNamespace()) {
            includeGlobalNamespace = true;
        } else if (!child.isImplicitlyDeclared()) {
            namespacesWithTypeMember.add(namespaceSymbol);
        }
    }
}

