private static int calculateMaintainabilityIndex(ComputationalComplexityMetrics computationalComplexityMetrics, int cyclomaticComplexity) {
    double computationalComplexityVolume = Math.max(0.0, Math.log(computationalComplexityMetrics.getVolume())); // avoid Log(0) = -Infinity
    double logEffectiveLinesOfCode = Math.max(0.0, Math.log(computationalComplexityMetrics.getEffectiveLinesOfCode())); // avoid Log(0) = -Infinity

    double rawMI = 171 - 5.2 * computationalComplexityVolume - 0.23 * cyclomaticComplexity - 16.2 * logEffectiveLinesOfCode;

    return MetricsHelper.normalizeAndRoundMaintainabilityIndex(rawMI);
}

