static void removeContainingTypes(ISymbol symbol, Set<INamedTypeSymbol> coupledTypesBuilder) {
    INamedTypeSymbol namedType = (symbol instanceof INamedTypeSymbol) 
                                 ? (INamedTypeSymbol) symbol 
                                 : symbol.getContainingType();
    while (namedType != null) {
        coupledTypesBuilder.remove(namedType);
        namedType = namedType.getContainingType();
    }
}

static List<IParameterSymbol> getParameters(ISymbol member) {
    switch (member.getKind()) {
        case METHOD:
            return ((IMethodSymbol) member).getParameters();
        case PROPERTY:
            return ((IPropertySymbol) member).getParameters();
        default:
            return Collections.emptyList();
    }
}

